function AuthScreen({onDemo}:{onDemo:()=>void}) {
 const [mode,setMode]=useState<'login'|'signup'|'reset'>('login');const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[error,setError]=useState('');const[notice,setNotice]=useState('');const[busy,setBusy]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setError('');setNotice('');setBusy(true);try{if(mode==='reset'){const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:`${window.location.origin}/reset-password`});if(error)throw error;setNotice('Изпратихме инструкции за възстановяване на пощата Ви.')}else if(mode==='signup'){const {error}=await supabase.auth.signUp({email,password});if(error)throw error;setNotice('Проверете пощата си за потвърждение на регистрацията.')}else{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;}}catch(err){setError(err instanceof Error?err.message:'Неуспешна заявка.')}finally{setBusy(false)}}
 return <main className="grid min-h-screen place-items-center bg-background px-4"><div className="w-full max-w-[400px]"><div className="mb-8 text-center"><img src="/lekar-ai-logo-20261005.png" alt="Lekar AI" width={48} height={48} className="mx-auto mb-5 size-12 rounded-xl"/><h1 className="text-3xl font-semibold">Lekar<span className="text-primary">.ai</span></h1><p className="mt-2 text-sm text-muted-foreground">Клинична документация, подредена с внимание.</p></div><div className="rounded-xl border border-border bg-card p-7 shadow-sm"><div className="mb-6"><h2 className="text-xl font-semibold">{mode==='login'?'Добре дошли':mode==='signup'?'Създайте профил':'Нова парола'}</h2><p className="mt-1 text-sm text-muted-foreground">{mode==='reset'?'Ще изпратим връзка за възстановяване.':'Влезте в защитеното си работно пространство.'}</p></div><form onSubmit={submit} className="space-y-4"><label className="block text-xs font-medium">Имейл<Input className="mt-1.5 h-10" type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="doctor@example.com"/></label>{mode!=='reset'&&<label className="block text-xs font-medium">Парола<Input className="mt-1.5 h-10" type="password" required minLength={6} autoComplete={mode==='signup'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></label>}<Button disabled={busy} className="h-10 w-full">{busy?'Моля, изчакайте…':mode==='login'?'Вход':mode==='signup'?'Регистрация':'Изпрати връзка'}</Button></form>{mode!=='reset'&&<><div className="my-5 flex items-center gap-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border"/>или<span className="h-px flex-1 bg-border"/></div><Button variant="outline" className="w-full" onClick={async()=>{setError('');const result=await lovable.auth.signInWithOAuth('google',{redirect_uri:window.location.origin});if(result.error)setError(result.error.message)}}>Продължи с Google</Button></>}<ErrorLine message={error}/>{notice&&<p role="status" className="mt-3 text-xs text-primary">{notice}</p>}<div className="mt-6 flex flex-wrap justify-between gap-2 text-xs"><Button variant="link" size="sm" className="px-0" onClick={()=>{setMode(mode==='signup'?'login':'signup');setError('')}}>{mode==='signup'?'Имам профил':'Създай профил'}</Button><Button variant="link" size="sm" className="px-0" onClick={()=>{setMode(mode==='reset'?'login':'reset');setError('')}}>{mode==='reset'?'Към вход':'Забравена парола?'}</Button></div></div><Button variant="outline" className="mt-5 h-11 w-full border-primary text-primary" onClick={onDemo}>Разгледай демо <span className="text-xs font-normal">· синтетични данни</span></Button><p className="mt-4 text-center text-xs text-muted-foreground">Демото не съдържа реални пациентски данни.</p></div></main>
}
function LangSelect({language,onChange,className=''}:{language:Language;onChange:(l:Language)=>void;className?:string}){return <div role="group" aria-label={ui[language].langLabel} className={`inline-flex rounded-md border border-border bg-card p-0.5 text-xs ${className}`}>{(['bg','en'] as Language[]).map(l=><button key={l} type="button" lang={l} aria-pressed={language===l} onClick={()=>onChange(l)} className={`rounded px-2.5 py-1 ${language===l?'bg-secondary font-semibold text-primary':'text-muted-foreground'}`}>{l==='bg'?'Български':'English'}</button>)}</div>}
function DemoLanding({onEnter,onLogin,busy,error,language,onLanguage,pending,onLogout}:{onEnter:()=>void;onLogin:()=>void;busy:boolean;error:string;language:Language;onLanguage:(l:Language)=>void;pending?:boolean;onLogout?:()=>void}){
 const[ack,setAck]=useState(false);const t=ui[language];
 return <main className="grid min-h-screen place-items-center bg-background px-4 py-10"><div className="w-full max-w-[520px]"><div className="mb-4 flex justify-center"><LangSelect language={language} onChange={onLanguage}/></div><div className="mb-6 text-center"><img src="/lekar-ai-logo-20261005.png" alt="Lekar AI" width={48} height={48} className="mx-auto mb-4 size-12 rounded-xl"/><h1 className="text-3xl font-semibold">{t.landingTitle}</h1><p className="mt-2 text-sm text-muted-foreground">{t.landingSub}</p></div><div className="rounded-xl border border-border bg-card p-6 shadow-sm sm:p-7">{pending&&<div role="status" className="mb-4 rounded-lg border border-border bg-secondary p-4 text-xs leading-5 text-primary"><strong className="block">{t.notApprovedTitle}</strong>{t.notApprovedText}</div>}<div role="note" className="rounded-lg border border-warning/40 bg-warning/10 p-4 text-sm font-medium leading-6 text-warning-foreground">{t.landingWarning}</div><ul className="mt-4 space-y-1.5 text-xs leading-5 text-muted-foreground"><li>{t.landing1}</li><li>{t.landing2}</li><li>{t.landing3(DEMO_QUOTAS.recordings,DEMO_QUOTAS.reports,DEMO_QUOTAS.assistant)}</li></ul><label className="mt-5 flex cursor-pointer items-start gap-3 rounded-lg border border-border bg-background p-4 text-xs leading-5"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)} className="mt-1 accent-primary" aria-label={t.ackAria}/><span>{t.ack}</span></label><Button disabled={!ack||busy} className="mt-5 h-11 w-full" onClick={onEnter}>{busy?t.starting:t.enter}</Button><ErrorLine message={error}/></div><div className="mt-4 text-center">{onLogout?<Button variant="link" size="sm" className="text-xs text-muted-foreground" onClick={onLogout}>{t.logout}</Button>:<Button variant="link" size="sm" className="text-xs text-muted-foreground" onClick={onLogin}>{t.loginLink}</Button>}</div></div></main>
}
