 const[integration,setIntegration]=useState<{sonioxConfigured:boolean;aiConfigured:boolean}|null>(null);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[save,setSave]=useState<'saved'|'saving'|'error'>('saved');const[notice,setNotice]=useState('');const[ask,setAsk]=useState('');const[target,setTarget]=useState<SectionKey>('anamneza');const[newName,setNewName]=useState('');const[newIdentifier,setNewIdentifier]=useState('');const[newMode,setNewMode]=useState<'conversation'|'dictation'>('conversation');const[consent,setConsent]=useState(false);const[speaker,setSpeaker]=useState<'doctor'|'patient'>('doctor');const[manual,setManual]=useState('');const[recording,setRecording]=useState<'idle'|'active'|'paused'|'stopping'>('idle');const[elapsed,setElapsed]=useState(0);const[interim,setInterim]=useState('');const lastFinalEnd=useRef(-1);const finalBuffer=useRef(new FinalUtteranceBuffer('idle'));const seenSources=useRef<Set<string>>(new Set());const elapsedRef=useRef(0);const speakerRef=useRef<'doctor'|'patient'>('doctor');const pendingSegments=useRef<Set<Promise<unknown>>>(new Set());const transcriptFailure=useRef(false);const recordingSessionId=useRef<string|null>(null);const [chatBySession,setChatBySession]=useState<Record<string,{role:'user'|'assistant';content:string}[]>>({});const [chatLoading,setChatLoading]=useState(false);const demoToken=useRef<string>('');const demoGen=useRef(0);const[quotas,setQuotas]=useState<{recordings:number;reports:number;assistant:number}>({...DEMO_QUOTAS});const[showLogin,setShowLogin]=useState(false);const[entering,setEntering]=useState(false);const[landingError,setLandingError]=useState('');const recordStartRef=useRef(0);const recordLimitRef=useRef(0);const[voicePhrases,setVoicePhrases]=useState<VoicePhrase[]>([]);const voicePhrasesRef=useRef<VoicePhrase[]>([]);voicePhrasesRef.current=voicePhrases;const languageRef=useRef<Language>('bg');languageRef.current=language;const[vpOpen,setVpOpen]=useState(false);const[vpTry,setVpTry]=useState('');const[vpDraft,setVpDraft]=useState<VoicePhrase>({id:'draft',trigger:'',expansion:'',section:'status',language:'bg',enabled:true});const[vpDraftErr,setVpDraftErr]=useState('');
 const recordingRef=useRef<ReturnType<SonioxClient['realtime']['record']>|null>(null);const finishRef=useRef<()=>Promise<void>>(async()=>{});const timerRef=useRef<ReturnType<typeof setInterval>|null>(null);const saveTimers=useRef<Record<string,ReturnType<typeof setTimeout>>>({});const saveQueues=useRef<Record<string,Promise<void>>>({});const saveVersions=useRef<Record<string,number>>({});const ownerRef=useRef<string|null>(null);const[authUid,setAuthUid]=useState<string|null>(null);const invalidateRef=useRef<()=>void>(()=>{});sessionsRef.current=sessions;const selectedSession=sessions.find(s=>s.id===selected);const answer=chatBySession[selected]?.filter(m=>m.role==='assistant').at(-1)?.content||'';const t=ui[language];const sectionLabels=sectionLabelsByLang[language];const dateBg=(d:string)=>dateFor(language,d);const err=(e:unknown,fallback:string)=>localizeError(language,e instanceof Error?e.message:undefined,fallback);
 useEffect(()=>{let saved:string|null=null;try{saved=sessionStorage.getItem(LANG_STORAGE_KEY)}catch{}setLanguage(isLanguage(saved)?saved:detectLanguage(navigator))},[]);
