  useEffect(()=>{/* Sticky source invalidation for every session's documents, whichever tab/session is shown. */const cur=docsRef.current;let any=false;const next:Record<string,SessionDocs>={...cur};for(const id of Object.keys(cur)){const s=sessions.find(x=>x.id===id);if(!s)continue;const r=invalidateDocs(cur[id]!,s);if(r.changed){next[id]=r.docs;any=true}}if(any){docsRef.current=next;setDocsBySession(next)}},[sessions,docsBySession]);
 function chooseLanguage(l:Language){setLanguage(l);try{sessionStorage.setItem(LANG_STORAGE_KEY,l)}catch{}}
 useEffect(()=>{supabase.auth.getUser().then(({data})=>{setAuthUid(data.user?.id??null);setAuth(data.user?'signed':'out')});const {data:{subscription}}=supabase.auth.onAuthStateChange((event,session)=>{const uid=session?.user?.id??null;setAuthUid(event==='SIGNED_OUT'?null:uid);if(event!=='SIGNED_OUT'&&uid&&ownerRef.current&&uid!==ownerRef.current){/* Auth identity switched: old callbacks must not touch the new workspace. */teardownRef.current();invalidateRef.current();setSessions([]);setSelected('');setChatBySession({});setApproved('unknown')}if(event==='SIGNED_IN')setAuth('signed');if(event==='SIGNED_OUT'){teardownRef.current();invalidateRef.current();setSelected('');setAuth('out');setApproved('unknown');setDemo(false);setSessions([]);setRole(false);setIntegration(null);setChatBySession({})}});return()=>subscription.unsubscribe()},[]);
