 async function persistSection(id:string,key:SectionKey,content:string,verified_at:string|null){if(demo){setSave('saved');return;}const gen=demoGen.current;const owner=ownerRef.current;const queueKey=`${id}:${key}`;const version=(saveVersions.current[queueKey]||0)+1;saveVersions.current[queueKey]=version;setSave('saving');const pending=(saveQueues.current[queueKey]||Promise.resolve()).catch(()=>{}).then(async()=>{if(gen!==demoGen.current||!owner)return;try{const {data:{user}}=await supabase.auth.getUser();if(gen!==demoGen.current)return;if(!user||user.id!==owner)throw Error('Няма активен профил.');const {error}=await supabase.from('report_sections').upsert({consultation_id:id,clinician_id:owner,section:key,content,verified_at},{onConflict:'consultation_id,section'});if(error)throw error;if(gen===demoGen.current&&saveVersions.current[queueKey]===version)setSave('saved')}catch(e){if(gen!==demoGen.current)return;if(saveVersions.current[queueKey]===version)setSave('error');setError(e instanceof Error?e.message:'Неуспешно запазване.');throw e}});saveQueues.current[queueKey]=pending;await pending}
 function editSection(id:string,key:SectionKey,content:string){changeSession(id,s=>applyEdit(s,key,content));if(!demo)setSave('saving');const timerKey=`${id}:${key}`;clearTimeout(saveTimers.current[timerKey]);saveTimers.current[timerKey]=setTimeout(()=>{delete saveTimers.current[timerKey];void persistSection(id,key,content,null).catch(()=>{})},700)}
 function commitSection(id:string,key:SectionKey,content:string){const k=`${id}:${key}`;/* Blur without a pending edit keeps verification and enqueues nothing. */if(!saveTimers.current[k])return;clearTimeout(saveTimers.current[k]);delete saveTimers.current[k];void persistSection(id,key,content,null).catch(()=>{})}
 async function verifySection(id:string,key:SectionKey,content:string,current:string|null){clearTimeout(saveTimers.current[`${id}:${key}`]);delete saveTimers.current[`${id}:${key}`];const stamp=current?null:new Date().toISOString();changeSession(id,s=>applyVerify(s,key,stamp));await persistSection(id,key,content,stamp).catch(()=>{})}
 async function updateInstructions(id:string,value:string){changeSession(id,s=>({...s,patient_instructions:value}));if(demo)return;setSave('saving');const {error}=await supabase.from('consultations').update({patient_instructions:value,updated_at:new Date().toISOString()}).eq('id',id);setSave(error?'error':'saved');if(error)setError(error.message)}
 async function addSegment(id:string,content:string,who:'doctor'|'patient'=speakerRef.current,speakerId?:string,sourceKey?:string,opts:{typed?:boolean}={}):Promise<VoicePhrase|null>{if(!content.trim())return null;if(sourceKey){if(seenSources.current.has(sourceKey))return null;seenSources.current.add(sourceKey)}const original=content.trim();const hit=demo&&who==='doctor'?matchPhrase(original,voicePhrasesRef.current,languageRef.current):null;const cleaned=hit?original:phrases.reduce((value,phrase)=>phrase.source.trim()?value.replaceAll(phrase.source,phrase.replacement):value,content.trim());/* Sequence is assigned synchronously at call time and persisted, so completion delays cannot reorder lines. */const seg:Segment={id:crypto.randomUUID(),speaker:who,text:cleaned,seconds:elapsedRef.current,speaker_id:speakerId||null,seq:nextSeq(),command:hit?{phraseId:hit.id,cue:original}:null};if(!demo){const write=segChain.current.catch(()=>{}).then(async()=>{const {data:{user}}=await supabase.auth.getUser();if(!user)throw Error('Необходим е вход.');const {error}=await supabase.from('transcript_segments').insert({id:seg.id,consultation_id:id,clinician_id:user.id,speaker:who,speaker_id:speakerId||null,text:seg.text,seconds:seg.seconds,client_seq:seg.seq??null});if(error)throw Error('Репликата не беше запазена: '+error.message)});segChain.current=write;try{await write}catch(e){transcriptFailure.current=true;setError(e instanceof Error?e.message:'Репликата не беше запазена.');return null}}changeSession(id,s=>({...s,segments:insertBySeq(s.segments,seg)}));/* Only a typed submit clears the typed draft; dictation never touches it. */if(opts.typed)setManual(prev=>prev===content?'':prev);if(hit){applyExpansion(id,sourceKey??`typed:${seg.id}`,original,hit,false,seg.id);return hit}return null}
  function applyExpansion(id:string,sourceKey:string,cue:string,p:VoicePhrase,manual:boolean,segmentId:string|null=null){changeSession(id,s=>applyExpansionTo(s,sourceKey,cue,p,{id:crypto.randomUUID(),at:new Date().toISOString(),manual,segmentId}));setNotice(ui[languageRef.current].vpInserted(sectionLabelsByLang[languageRef.current][p.section]))}
  function undoExpansion(id:string){const s=sessionsRef.current.find(x=>x.id===id);if(!s)return;const r=undoLatest(s);changeSession(id,x=>undoLatest(x).session);if(r.ok)setNotice(t.vpUndone);else if(r.reason==='changed')setError(t.vpUndoMissing)}
  function addVoicePhrase(){const problem=validatePhrase(vpDraft,voicePhrases);if(problem){setVpDraftErr(problem==='empty'?t.vpEmpty:problem==='emptyText'?t.vpEmptyText:t.vpDuplicate);return}setVoicePhrases(prev=>[...prev,{...vpDraft,id:crypto.randomUUID(),trigger:vpDraft.trigger.trim(),expansion:vpDraft.expansion.trim()}]);setVpDraft(d=>({...d,trigger:'',expansion:''}));setVpDraftErr('')}
 async function createSession(){if(newMode==='conversation'&&!consent){setError(t.needConsent);return}setBusy(true);setError('');try{const session=blankSession(newName.trim(),newIdentifier.trim(),newMode,newMode==='conversation'&&consent);if(!demo){const {data:{user}}=await supabase.auth.getUser();if(!user)throw Error('Необходим е вход.');const {error}=await supabase.from('consultations').insert({id:session.id,clinician_id:user.id,patient_name:session.patient_name,patient_identifier:session.patient_identifier,mode:session.mode,status:'draft',consent_at:session.consent_at,consent_notice_version:session.consent_at?'v1.0':null});if(error)throw error}setSessions(prev=>[session,...prev]);setSelected(session.id);elapsedRef.current=0;setElapsed(0);setView('workspace');setNewName('');setNewIdentifier('');setConsent(false);setNotice(t.created)}catch(e){setError(err(e,t.createFail))}finally{setBusy(false)}}
 async function startRecording(){if(!selectedSession||recordingSessionId.current)return;if(selectedSession.mode==='conversation'&&!selectedSession.consent_at){setError(t.noConsentRec);return}setError('');const sessionId=selectedSession.id;const mode=selectedSession.mode;const startDuration=selectedSession.duration_seconds;const demoAtStart=demoGen.current;const gen=lifecycle.current.begin(sessionId);const stale=()=>!lifecycle.current.isCurrent(gen,sessionId)||demoAtStart!==demoGen.current;recordingSessionId.current=sessionId;transcriptFailure.current=false;pendingSegments.current.clear();try{let api_key:string;let maxSeconds:number;if(demo){const r=await demoSonioxKey({data:{token:demoToken.current}});api_key=r.api_key;maxSeconds=r.maxSeconds;if(!stale())setQuotas(q=>({...q,recordings:Math.max(0,r.remaining)}))}else{const r=await getSonioxKey({data:{id:sessionId}});api_key=r.api_key;maxSeconds=r.maxSeconds}if(stale())return;recordLimitRef.current=maxSeconds;recordStartRef.current=startDuration;const client=new SonioxClient({config:{api_key,region:'us'}});lastFinalEnd.current=-1;finalBuffer.current=new FinalUtteranceBuffer(crypto.randomUUID());elapsedRef.current=startDuration;setElapsed(startDuration);const rec=client.realtime.record({model:'stt-rt-v5',buffer_queue_size:100,auto_reconnect:false,language_hints:language==='bg'?['bg']:['en'],enable_speaker_diarization:mode==='conversation',enable_endpoint_detection:true});if(!lifecycle.current.attach(gen,rec))return;recordingRef.current=rec;rec.on('result',result=>{if(stale())return;setInterim(result.tokens.filter(token=>!token.is_final).map(token=>token.text).join(''));/* Soniox sends each final token exactly once; keep all of them, including punctuation with equal timestamps. */finalBuffer.current.add(result.tokens,mode==='conversation')});rec.on('endpoint',()=>{if(!stale())flushTranscript(sessionId,mode)});rec.on('error',e=>{if(stale())return;const l=languageRef.current;setError(localizeError(l,e.message,ui[l].recInterrupted)+' '+ui[l].recProviderEnded);/* Keep already received final tokens: finish flushes and saves them, then restores idle controls. */void finishRecording({providerEnded:true})});rec.on('connected',()=>{if(stale())return;lifecycle.current.providerStartedAt=Date.now();setRecording('active');tickStart();wallStart(gen)});if(!demo){const {error:statusError}=await supabase.from('consultations').update({status:'recording'}).eq('id',sessionId);if(statusError)throw statusError}}catch(e){if(stale())return;teardownRecording();setError(err(e,t.micUnavailable))}}
 async function finishRecording(opts:{providerEnded?:boolean}={}):Promise<boolean>{const id=recordingSessionId.current;if(!id||finishingRef.current)return false;finishingRef.current=true;let ok=false;const gen=lifecycle.current.gen;const current=()=>gen===lifecycle.current.gen;setRecording('stopping');tickStop();lifecycle.current.removeTimer(wallTimerRef.current);wallTimerRef.current=null;try{if(!opts.providerEnded){try{await recordingRef.current?.stop()}catch{transcriptFailure.current=true}}if(!current())return false;flushTranscript(id,sessions.find(s=>s.id===id)?.mode||'dictation');await Promise.all([...pendingSegments.current]);if(!current())return false;if(transcriptFailure.current)throw Error(t.segsLost);if(!demo){const {error:durationError}=await supabase.from('consultations').update({status:'draft',duration_seconds:elapsedRef.current}).eq('id',id);if(durationError)throw durationError}changeSession(id,s=>({...s,status:'draft',duration_seconds:elapsedRef.current}));if(!opts.providerEnded)setNotice(t.recDone);ok=true}catch(e){if(!current())return false;setError(err(e,t.recFail));changeSession(id,s=>({...s,status:'draft',duration_seconds:elapsedRef.current}));if(!demo){const {error:statusError}=await supabase.from('consultations').update({status:'draft',duration_seconds:elapsedRef.current}).eq('id',id);if(statusError)setError('Записът не завърши и статусът не се запази: '+statusError.message)}}finally{finishingRef.current=false;if(current())teardownRecording()}return ok&&current()}
 finishRef.current=async()=>{await finishRecording()};
 async function makeReport(){if(!selectedSession)return;if(recordingSessionId.current){setError(t.finishFirst);return}await Promise.all([...pendingSegments.current]);if(transcriptFailure.current){setError(t.unsaved);return}const gen=demoGen.current;const s0=sessionsRef.current.find(s=>s.id===selectedSession.id)??selectedSession;const sessionId=s0.id;const startRevs=snapshotRevisions(s0);const evidence=evidenceSegments(s0.segments,s0.expansions);const expansionSections=keys.filter(k=>(s0.expansions||[]).some(e=>isActive(e)&&e.section===k));if(!evidence.length&&!expansionSections.length){setError(t.needEvidence);return}if(evidence.length){const c=checkBudget(evidence,demo?DEMO_REPORT_BUDGET:CLINICAL_REPORT_BUDGET);if(!c.ok){setError(t.tooLong(c.problem));return}}if(demo&&(specialty.length>120||instructions.length>600)){setError(t.tooLong('total'));return}const keep=new Set<SectionKey>();if(!evidence.length)keys.filter(k=>!expansionSections.includes(k)).forEach(k=>keep.add(k));const prot=protectedSections(s0).filter(k=>!keep.has(k));if(prot.length&&!window.confirm(t.overwriteAsk(prot.map(k=>sectionLabels[k]).join(', '))))prot.forEach(k=>keep.add(k));if(keep.size===keys.length){setNotice(t.nothingReplaced);return}setBusy(true);setError('');try{let usedPreset:{template:string;style:string}|null=null;let draft:Record<SectionKey,string>={anamneza:'',status:'',izsledvania:'',terapia:''};if(evidence.length){if(demo){const r=await demoReport({data:{token:demoToken.current,segments:evidence.map(s=>({speaker:s.speaker,speaker_id:s.speaker_id??null,text:s.text})),specialty,instructions,language,template:preset.template,style:preset.style}});if(gen!==demoGen.current)return;draft=r.report;usedPreset=r.preset;setQuotas(q=>({...q,reports:Math.max(0,r.remaining)}))}else{draft=await generateReport({data:{id:sessionId}});if(gen!==demoGen.current)return}}/* Merge against the LATEST state with revision guards captured at request start. */const latest=sessionsRef.current.find(s=>s.id===sessionId);if(!latest)return;const m=mergeGenerated(latest,draft,startRevs,keep);changeSession(sessionId,s=>{const n=mergeGenerated(s,draft,startRevs,keep).session;return usedPreset?{...n,report_preset:usedPreset}:n});/* Enqueue every replacement synchronously so later manual edits queue AFTER generated content. */if(!demo){const results=await Promise.allSettled(m.replaced.map(k=>persistSection(sessionId,k,m.session.sections[k].content,null)));if(gen!==demoGen.current)return;const failed=m.replaced.filter((_,i)=>results[i]?.status==='rejected');if(failed.length){/* Draft is generated and shown; only persistence failed for these sections. */setSave('error');setError(t.partialSave(failed.map(k=>sectionLabels[k]).join(', ')));return}}if(gen!==demoGen.current)return;setNotice(t.draftReady+(m.skipped.length?' '+t.keptSections(m.skipped.map(k=>sectionLabels[k]).join(', ')):''))}catch(e){if(gen===demoGen.current)setError(err(e,t.genFail))}finally{if(gen===demoGen.current)setBusy(false)}}
 async function sendQuestion(){if(!selectedSession||!ask.trim())return;const question=ask;if(question.trim().length>QUESTION_MAX_CHARS){setError(t.tooLong('segment'));return}const sessionId=selectedSession.id;const evidence=evidenceSegments(selectedSession.segments,selectedSession.expansions);const c=checkBudget(evidence,demo?DEMO_ASSISTANT_BUDGET:CLINICAL_ASSISTANT_BUDGET,true);if(!c.ok){setError(t.tooLong(c.problem));return}setBusy(true);setError('');const gen=demoGen.current;try{if(demo){const r=await demoAssistant({data:{token:demoToken.current,language,question,segments:evidence.map(s=>({speaker:s.speaker,speaker_id:s.speaker_id??null,text:s.text})),history:(chatBySession[sessionId]||[]).slice(-10).map(m=>({role:m.role,content:m.content}))}});if(gen!==demoGen.current)return;setQuotas(q=>({...q,assistant:Math.max(0,r.remaining)}));setChatBySession(prev=>({...prev,[sessionId]:[...(prev[sessionId]||[]),{role:'user',content:question},{role:'assistant',content:r.text}]}));setAsk(prev=>prev===question?'':prev);return}const owner=ownerRef.current;if(!owner)return;const response=await askAssistant({data:{id:sessionId,question}});if(gen!==demoGen.current)return;const {data:{user}}=await supabase.auth.getUser();if(gen!==demoGen.current)return;if(!user||user.id!==owner)throw Error('Няма активен профил.');const {error:chatError}=await supabase.from('session_chat_messages').insert([{consultation_id:sessionId,clinician_id:owner,role:'user',content:question},{consultation_id:sessionId,clinician_id:owner,role:'assistant',content:response.text}]);if(gen!==demoGen.current)return;if(chatError)throw Error('Предложението е получено, но историята не беше запазена: '+chatError.message);setChatBySession(prev=>({...prev,[sessionId]:[...(prev[sessionId]||[]),{role:'user',content:question},{role:'assistant',content:response.text}]}));setAsk(prev=>prev===question?'':prev)}catch(e){if(gen===demoGen.current)setError(err(e,t.noAnswer))}finally{if(gen===demoGen.current)setBusy(false)}}
 async function copy(value:string,unverified=false){try{await navigator.clipboard.writeText(demo?`${t.exportHeader}\n\n${value}`:value);setNotice(unverified?t.copiedUnverified:t.copied)}catch{setError(t.copyDenied)}}
